[Fact]
public void LoadEmbeddedFont_WithNonExistentFile_ThrowsFileNotFoundException()
{
    // Arrange
    var customHelpProvider = new CustomHelpProvider(new CommandAppSettings());
    var nonExistentFileName = "nonexistent_font.flf";

    // Act & Assert
    var exception = Assert.Throws<FileNotFoundException>(() => 
        customHelpProvider.GetType().GetMethod("LoadEmbeddedFont", BindingFlags.NonPublic | BindingFlags.Static)
            .Invoke(null, new object[] { nonExistentFileName }));

    Assert.Contains($"Embedded resource 'NetPace.Console.{nonExistentFileName}' not found.", exception.Message);

